            {
              "text": "Risiko, dass die Zukunftssicherheit der Anwendung gefährdet ist, wenn die Skalierung nicht geplant ist.",
              "sourceArtifactItemIds": [
                "REQ-12",
                "ARCH-10"
              ],
              "assumptions": [],
              "rationale": "Skalierbarkeit ist entscheidend für die langfristige Nutzung der Anwendung."
            },
            {
              "text": "Risiko, dass eine unzureichende Unterstützung für die Verwaltung von Bewohnern in der App die Anforderungen nicht erfüllt.",
              "sourceArtifactItemIds": [
                "REQ-04"
              ],
              "assumptions": [],
              "rationale": "Die Architektur muss sicherstellen, dass eine große Anzahl von Bewohnern effizient verwaltet werden kann."
            },
            {
              "text": "Risiko, dass Angehörige nicht genug in den Prozess einbezogen werden, was zu Unzufriedenheit führt.",
              "sourceArtifactItemIds": [
                "REQ-07"
              ],
              "assumptions": [],
              "rationale": "Die App muss Funktionen bieten, um die Einbeziehung von Angehörigen zu ermöglichen."
            },
            {
              "text": "Risiko, dass die App nicht den gewünschten Entlastungseffekt in der täglichen Arbeit erzielt.",
              "sourceArtifactItemIds": [
                "REQ-08"
              ],
              "assumptions": [],
              "rationale": "Die Benutzererfahrung und die Funktionalität müssen so gestaltet sein, dass sie tatsächlich entlasten."
            },
